std::vector<std::vector<Point2d>> result;
    if (points.empty()) return result;

    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef CGAL::Delaunay_triangulation_2<K> DT;
    typedef CGAL::Delaunay_triangulation_adaptation_traits_2<DT> AT;
    typedef CGAL::Delaunay_triangulation_caching_degeneracy_removal_policy_2<DT> AP;
    typedef CGAL::Voronoi_diagram_2<DT, AT, AP> VD;

    DT dt;
    for (const auto& p : points) {
        dt.insert(K::Point_2(p.x(), p.y()));
    }

    VD vd(dt);

    result.resize(dt.number_of_vertices());
    std::map<typename VD::Vertex_handle, size_t> vertexMap;
    size_t vertexIndex = 0;

    for (typename VD::Finite_vertices_iterator vit = vd.finite_vertices_begin(); vit != vd.finite_vertices_end(); ++vit) {
        vertexMap[vit] = vertexIndex++;
    }

    for (typename VD::Finite_faces_iterator fit = vd.finite_faces_begin(); fit != vd.finite_faces_end(); ++fit) {
        if (!vd.is_infinite(fit)) {
            size_t siteIndex = 0;
            for (typename DT::Finite_vertices_iterator vit = dt.finite_vertices_begin(); vit != dt.finite_vertices_end(); ++vit) {
                if (dt.number_of_vertices() > siteIndex && dt.point(vit) == fit->vertex(0)->point()) {
                    break;
                }
                siteIndex++;
            }
            if (siteIndex >= result.size()) continue;

            std::vector<Point2d> cell;
            typename VD::Ccb_halfedge_circulator circ = vd.ccb(fit->halfedge());
            typename VD::Ccb_halfedge_circulator start = circ;

            do {
                if (!vd.is_infinite(circ)) {
                    K::Point_2 p = circ->vertex()->point();
                    cell.emplace_back(p.x(), p.y());
                }
                ++circ;
            } while (circ != start);

            result[siteIndex] = cell;
        }
    }

    // Handle case where some cells might be empty due to indexing mismatch
    for (size_t i = 0; i < result.size(); ++i) {
        if (result[i].empty()) {
            typename DT::Vertex_handle vh = dt.vertex(i);
            if (vh != DT::Vertex_handle()) {
                K::Point_2 p = vh->point();
                result[i].emplace_back(p.x(), p.y());
            }
        }
    }

    return result;

